#[Hook('entity_presave')]
public function trimNodeTitle(EntityInterface $entity): void {
  if (!$entity instanceof NodeInterface) {
    return;
  }
  $entity->setTitle($this->cleanTitle((string) $entity->getTitle()));
}

private function cleanTitle(string $title): string {
  return preg_replace('/\s+/', ' ', trim($title));
}

#[Hook('entity_presave')]
public function fillArticleDescription(EntityInterface $entity): void {
  if (!$entity instanceof NodeInterface || $entity->bundle() != 'article') {
    return;
  }
  if ($entity->get('field_description')->isEmpty() && !$entity->get('field_content')->isEmpty()) {
    $text = strip_tags($entity->get('field_content')->value);
    $entity->set('field_description', Unicode::truncate(trim($text), 200, TRUE, TRUE));
  }
}

#[Hook('entity_presave')]
public function logNodeEditor(EntityInterface $entity): void {
  if (!$entity instanceof NodeInterface) {
    return;
  }
  $this->loggerFactory->get('jddoesdev_core')->notice('%title saved by %user.', [
    '%title' => $entity->label(),
    '%user' => $this->currentUser->getAccountName(),
  ]);
}

/**
 * Implements hook_requirements().
 */
function jddoesdev_core_requirements($phase) {
  $requirements = array();
  if ($phase == 'runtime') {
    // Added after the 2019 incident where stack traces showed on live.
    if (\Drupal::config('system.logging')->get('error_level') == 'verbose') {
      $requirements['jddoesdev_core_error_level'] = [
        'title' => t('Error message display'),
        'value' => t('Verbose'),
        'description' => t('Error messages, including backtraces, are shown to site visitors. Switch this off on production.'),
        'severity' => REQUIREMENT_WARNING,
      ];
    }
  }
  return $requirements;
}

public function __construct(
  protected readonly ConfigFactoryInterface $configFactory,
) {}

#[Hook('runtime_requirements')]
public function runtime(): array {
  $requirements = [];
  // Added after the 2019 incident where stack traces showed on live.
  if ($this->configFactory->get('system.logging')->get('error_level') == 'verbose') {
    $requirements['jddoesdev_core_error_level'] = [
      'title' => $this->t('Error message display'),
      'value' => $this->t('Verbose'),
      'description' => $this->t('Error messages, including backtraces, are shown to site visitors. Switch this off on production.'),
      'severity' => RequirementSeverity::Warning,
    ];
  }
  return $requirements;
}

